(* [comment removed for export] *)
Definition stashed (P : Prop) : Prop := P.
Ltac stash H := lazymatch type of H with ?T => change T with (stashed T) in H end.
Ltac unstash H := unfold stashed in H.

(* [comment removed for export] *)
Definition kept (P : Prop) : Prop := P.
Ltac tr_parked2 MU WM TAC :=
  lazymatch type of MU with munch _ _ ?mb =>
    repeat (lazymatch goal with
      | K : parked (rw_cells _ ?mx _ _) |- _ =>
          unfold parked in K;
          tryif constr_eq mx mb then idtac else first [tr_keep K over MU WM by TAC | fail 100 "tr_parked2: cannot transport" K];
          lazymatch type of K with ?T => change T with (kept T) in K end
      | K : parked (bytes_at _ ?mx _ _) |- _ =>
          unfold parked in K;
          tryif constr_eq mx mb then idtac else first [tr_keep K over MU WM by TAC | fail 100 "tr_parked2: cannot transport" K];
          lazymatch type of K with ?T => change T with (kept T) in K end
      | _ => fail end);
    repeat match goal with K : kept ?T |- _ => change (kept T) with (parked T) in K end
  end.

Section SETUP.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis SSF8 : set_shadow_stmt 0xf8 ASET_SHADOW_F8.
  Hypothesis SS00 : set_shadow_stmt 0x00 ASET_SHADOW_00.
  Hypothesis FREE7 : stack_free_7_stmt H.
  Hypothesis MEMCPY : asan_memcpy_stmt.
  Hypothesis ASSIGNA : aassignA_stmt.
  Hypothesis DOF : dof_stmt H.
  Hypothesis PF : pf_stmt.
Scheme kc__4 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

