Lemma ipf_setupB : forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s7x s9x t3 t4 t5 t6 h3 : word)
    (LF : list fframe) (m m2 : mem) (spa : Z) (gsz : nat)
    (gj j0 x24 x32 x40 x48 x56 x64 x72 x80 x88 x96 x104 x112 j128 jt x176 eb bb jr jh : list byte)
    (s : as_St H) (LB : list block)
    (P IN E p0 lo shi ff fp : Z) (bs : list byte) (c : pcore) (pad7 pad2 : list byte) (g : bool),
  rw_cells asegs m2 spa [CB 24 j0; CB 8 x24; CB 8 x32; CB 8 x40; CB 8 x48; CB 8 x56; CB 8 x64; CB 8 x72; CB 8 x80; CB 8 x88; CB 8 x96; CB 8 x104; CB 8 x112;
                         C8 (wz (p0 + Z.of_nat (length bs))); CB 16 j128; C8 (wz ff)] ->
  rw_cells asegs m2 (spa + 152) [CB 24 jt] -> rw_cells asegs m2 (spa + 176) [CB 8 x176] ->
  rw_cells asegs m2 (spa + 184) [CB 16 (poison_bytes 16 0)] -> rw_cells asegs m2 (spa + 200) [CB 16 (poison_bytes 16 0)] ->
  rw_cells asegs m2 (spa + 216) [CB gsz gj] ->
  rw_cells asegs m2 (bv_unsigned sp + -104) (dof_sav s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
  rw_cells asegs m2 ff [C8 (wz 0x41b58ab3); C8 (wz 0x13fb2); C8 (wz 0xd0474); C8 h3] -> rw_cells asegs m2 (ff + 32) [CB 8 eb; CB 4096 bb] ->
  rw_cells asegs m2 (ff + 4136) [CB 4048 jr] -> rw_cells asegs m2 (ff + 8184) [C8 (wz fp)] ->
  rw_cells asegs m2 (Z.shiftr ff 3 + 2147450880) [CB 4 (poison_bytes 4 0xf1)] ->
  rw_cells asegs m2 (Z.shiftr ff 3 + 2147450884) [CB 513 (poison_bytes 513 0xf8)] ->
  rw_cells asegs m2 (Z.shiftr ff 3 + 2147451397) [CB 35 (poison_bytes 35 0xf3)] ->
  rw_cells asegs m2 (Z.shiftr ff 3 + 2147450880 + 552) [CB 472 jh] ->
  rw_cells asegs m2 fp [C1 (b8 1)] ->
  rw_cells asegs m2 P (ParserCoreCells c pad7 pad2) -> rw_cells asegs m2 IN [C8 (wz p0)] -> rw_cells asegs m2 E (ErrCodeCells EC_clear) ->
  bytes_at asegs m2 p0 bs -> APfTab m2 -> (AFieldTabZero m2 \/ FT m2) -> FTInit m2 -> AHttpCat m2 g ->
  stk asegs m2 lo spa -> munch (ipf_WX H lo sp P IN E ff fp) m m2 -> wmono asegs m m2 -> mem_inv asegs m2 ->
  ipf_side H LF m m2 lo shi ff fp P E p0 (Z.of_nat (length bs)) ->
  ipf_bpure sp spa gsz P IN E lo shi c p0 (p0 + Z.of_nat (length bs)) bs -> bv_unsigned ra mod 2 = 0 ->
  as_RHEAP H s LB m2 -> aobj LB LF P 256 -> aobj LB LF E 24 -> aobj LB LF p0 (Z.of_nat (length bs)) ->
  tp = Z_to_bv 64 ATP -> (length LF + 2 < AFS_MAXLIVE)%nat ->
  evt asegs (ipf_segA_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc s LB LF spa gsz gj P IN E p0 lo shi ff fp
               (p0 + Z.of_nat (length bs)) bs c pad7 pad2 p0 p0 (wz 0x41b58ab3) (wz 0x13fb2) (wz 0xd0474) h3 j0 j128 jr jh m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             (wz ff) (wz E) (wz (sh7 ff)) (wz ff) (wz (sh7 ff + 4)) s7x (wz P) s9x (wz ASHADOW_BASE) (wz IN) t3 t4 t5 t6)
